function uploadPlan(type,size){return ['image/jpeg','image/png','image/webp','image/gif'].includes(type)&&size<=2000000?'asis':'convert';}
async function normalizeImage(file){
  const message='画像を変換できませんでした。JPEGかPNGの画像を選び直してください。';
  let image,url;
  try{
    if(typeof createImageBitmap==='function')image=await createImageBitmap(file);
    else{
      url=URL.createObjectURL(file);
      image=await new Promise((resolve,reject)=>{const value=new Image();value.onload=()=>resolve(value);value.onerror=reject;value.src=url;});
    }
    const width=image.width||image.naturalWidth,height=image.height||image.naturalHeight;
    if(!width||!height)throw Error(message);
    const scale=Math.min(1,1600/Math.max(width,height));
    const canvas=document.createElement('canvas');
    canvas.width=Math.max(1,Math.round(width*scale));canvas.height=Math.max(1,Math.round(height*scale));
    const context=canvas.getContext('2d');
    if(!context)throw Error(message);
    context.drawImage(image,0,0,canvas.width,canvas.height);
    const blob=await new Promise((resolve,reject)=>canvas.toBlob(value=>value?resolve(value):reject(Error(message)),'image/jpeg',0.85));
    if(blob.type==='image/jpeg')return blob;
    return new Blob([blob],{type:'image/jpeg'});
  }catch(error){throw Error(message);}
  finally{if(url)URL.revokeObjectURL(url);if(image&&typeof image.close==='function')image.close();}
}
const AUTH_REDIRECT='https://marks-tools.github.io/4study/#settings';
const modes={learning:'ラーニング',test:'通常テスト',stamina:'スタミナ'};
let client=null,repo=null,user=null,demo=true,books=[],questions=[],history=[],session=null,editor=null,dirty=false,saving=false,syncing=false,loaded=false,lastSync=null,pending=[],outboxBusy=false,authGeneration=0,objectUrls=[];
let listFilter={},studyFilter={},selectedBook='',currentMode='learning',draftTimer,noticeTimer;
let sfxEnabled=localStorage.getItem(SFX_KEY)!=='false',audioContext=null;
async function playAnswerSound(correct){
 if(!sfxEnabled)return;
 try{
  const AudioContext=window.AudioContext||window.webkitAudioContext;
  if(!AudioContext)return;
  audioContext||=new AudioContext();
  if(audioContext.state==='suspended')await audioContext.resume();
  const tone=(frequency,start,duration,type='sine')=>{const oscillator=audioContext.createOscillator(),gain=audioContext.createGain();oscillator.type=type;oscillator.frequency.value=frequency;gain.gain.setValueAtTime(.18,start);gain.gain.exponentialRampToValueAtTime(.001,start+duration);oscillator.connect(gain).connect(audioContext.destination);oscillator.start(start);oscillator.stop(start+duration);};
  const now=audioContext.currentTime;
  if(correct){tone(1047,now,.12);tone(1319,now+.13,.12);}else tone(150,now,.35,'square');
 }catch{}
}
const bulk=createBulkUI({app,context:()=>({user,repo,client,books,questions}),setBusy:value=>saving=value,refresh:()=>sync(false),notify:(m,e)=>toast(m,e),learn:ids=>{const chosen=ids.map(id=>questions.find(q=>q.id===id)).filter(Boolean);if(!chosen.length){toast('登録した問題を読み込めませんでした。一覧から再取得してください。',true);return;}session=createSession(structuredClone(chosen),'learning');enterQuestion(session);location.hash='#study';renderStudy();markViewed().catch(fail);}});
function showSavingDialog(){
  let overlay=$('#saving-dialog');
  if(!overlay){
    const style=document.createElement('style');
    style.textContent='@keyframes saving-dialog-spin{to{transform:rotate(360deg)}}#saving-dialog{position:fixed;inset:0;z-index:10000;display:grid;place-items:center;background:rgba(15,23,42,.55);pointer-events:auto}#saving-dialog[hidden]{display:none}#saving-dialog .saving-dialog-card{display:flex;align-items:center;gap:14px;min-width:220px;padding:22px 26px;border-radius:14px;background:#fff;color:#172033;box-shadow:0 18px 48px rgba(0,0,0,.28);font-weight:700}#saving-dialog .saving-dialog-spinner{width:24px;height:24px;border:3px solid #cbd5e1;border-top-color:#2563eb;border-radius:50%;animation:saving-dialog-spin .8s linear infinite}';
    document.head.append(style);
    overlay=document.createElement('div');
    overlay.id='saving-dialog';overlay.hidden=true;overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','登録しています');
    overlay.innerHTML='<div class="saving-dialog-card"><span class="saving-dialog-spinner" aria-hidden="true"></span><span>登録しています…</span></div>';
    document.body.append(overlay);
  }
  overlay.hidden=false;
}
function hideSavingDialog(){const overlay=$('#saving-dialog');if(overlay)overlay.hidden=true;}
function toast(message,error=false){clearTimeout(noticeTimer);$('#notice').textContent=message;$('#notice').className=error?'error':'';if(!error)noticeTimer=setTimeout(()=>$('#notice').textContent='',6500);}
function fail(e){toast('保存・通信処理を完了できませんでした。入力内容はこの端末に残しています。通信環境を確認してください。\n'+(e.message||e),true);}
function tempKey(name){return `yonstudy:${user?.id||'demo'}:${name}`;}
function setDemo(){const s=samples();books=[s.book];questions=s.questions;history=[];demo=true;loaded=true;}
function nav(){const path=location.hash.split('/')[0]||'#home';$('#nav').innerHTML=[['home','⌂','ホーム'],['list','▤','問題一覧'],['books','▤','問題集管理'],['edit','＋','問題作成'],['history','▥','学習履歴'],['settings','⚙','設定']].map(([p,i,n])=>`<a href="#${p}" ${path==='#'+p?'class="active" aria-current="page"':''}><b>${i}</b>${n}</a>`).join('');$('#account').textContent=user?'アカウント':'ログイン / 設定';}
function bookName(id){const b=books.find(b=>b.id===id);return b?bookLabel(b):'問題集';}
function stat(q){return progressFor(history.filter(h=>h.question_id===q.id));}
function rateLabel(s){return s.rate===null?'未挑戦':`正答率 ${Math.round(s.rate*100)}%（${s.correct}/${s.total}）`;}
function options(values,selected,empty='すべて'){return `<option value="">${empty}</option>`+values.map(v=>{const [id,name]=Array.isArray(v)?v:[v,v];return `<option value="${esc(id)}" ${String(selected)===String(id)?'selected':''}>${esc(name)}</option>`;}).join('');}
function unique(k){return [...new Set(questions.map(q=>q[k]).filter(Boolean))].sort();}
function summaryStats(){const a=history.filter(h=>h.mode!=='learning');return {rate:a.length?Math.round(100*a.filter(h=>h.is_correct).length/a.length):null,weak:questions.filter(q=>stat(q).weak).length};}
function syncLabel(){return demo?'サンプルを体験中':syncing?'クラウドを確認中…':lastSync?'最終同期 '+lastSync.toLocaleTimeString('ja-JP',{hour:'2-digit',minute:'2-digit'}):'クラウド未取得';}
function demoBanner(){return demo?'<div class="banner">サンプル体験中です。サンプルの学習履歴は画面を閉じるとリセットされます。自分の問題を保存するには <a href="#settings">ログイン</a> してください。</div>':'';}
function home(){const s=summaryStats();app.innerHTML=`<div class="intro"><div><div class="eyebrow">MY STUDY SPACE</div><h1>今日の一問を、確かな力に。</h1><p class="muted">覚える。試す。できるまで繰り返す。</p></div><div class="hero-actions"><button class="primary" data-go="edit">＋ 問題を登録</button></div></div>${demoBanner()}${!demo&&!loaded?'<div class="banner warn">クラウドのデータを読み込めていません。<button data-action="sync">再取得</button></div>':''}<div class="stats"><div class="stat"><strong>${questions.length} <small>問</small></strong><span>${demo?'サンプル問題':'登録済みの問題'}</span></div><div class="stat"><strong>${s.rate===null?'—':s.rate+'<small> %</small>'}</strong><span>これまでの正答率</span></div><div class="stat"><strong>${s.weak} <small>問</small></strong><span>もう一度学びたい苦手問題</span></div></div><div class="row between"><h2>学習をはじめる</h2><span class="sync">${syncLabel()}</span></div><div class="modes"><button class="mode" data-mode="learning"><span class="symbol">📖</span><strong>ラーニング</strong><small>正解を見ながら、じっくり理解。<br>解説・覚え方をまとめて確認。</small><span class="arrow">→</span></button><button class="mode test" data-mode="test"><span class="symbol">✎</span><strong>通常テスト</strong><small>4択・5択で、理解度チェック。<br>一問ずつ答え合わせ。</small><span class="arrow">→</span></button><button class="mode stamina" data-mode="stamina"><span class="symbol">🔥</span><strong>スタミナ</strong><small>間違えた問題を、もう一度。<br>すべて正解するまで挑戦。</small><span class="arrow">→</span></button></div><section class="section panel"><div class="row between"><h2>問題集</h2><button class="quiet" data-go="list">問題一覧へ →</button></div>${books.length?books.map(b=>`<div class="book"><span class="book-icon">▤</span><div class="grow"><strong>${esc(bookLabel(b))}</strong><small>${questions.filter(q=>q.question_book_id===b.id).length}問</small></div><button data-book="${b.id}">開く →</button></div>`).join(''):'<div class="empty"><strong>最初の問題集を作りましょう</strong>「問題集管理」から登録できます。</div>'}</section>${s.weak?'<button data-action="weak">苦手問題に取り組む →</button>':''}`;}
function filterFields(f,study=false){return `<label>問題集<select name="book">${options(books.map(b=>[b.id,bookLabel(b)]),f.book)}</select></label>${study?`<label>大分類<select name="category">${options(unique('category'),f.category)}</select></label>`:''}<label>ジャンル<select name="genre">${options(unique('genre'),f.genre)}</select></label><label>頻出ランク<select name="rank">${options([['A','A：頻出'],['B','B：標準'],['C','C：低頻度']],f.rank)}</select></label>${study?`<label>難易度<select name="difficulty">${options([1,2,3,4,5].map(n=>[n,'★'.repeat(n)]),f.difficulty)}</select></label><label>問題数<select name="count">${[10,15,20,'all'].map(n=>`<option value="${n}" ${String(f.count||10)===String(n)?'selected':''}>${n==='all'?'全問':n+'問'}</option>`).join('')}</select></label><label class="check"><input name="image" type="checkbox" ${f.image?'checked':''}>画像・図あり</label><label class="check"><input name="weak" type="checkbox" ${f.weak?'checked':''}>苦手問題のみ</label><label class="check"><input name="random" type="checkbox" ${f.random!==false?'checked':''}>問題の順序をランダムにする</label>`:''}`;}
function readFilters(form){const fd=new FormData(form),r=Object.fromEntries(fd);for(const k of ['image','weak','random'])r[k]=fd.has(k);return r;}
function list(){const filtered=filterQuestions(questions,listFilter,history);app.innerHTML=`<div class="row between"><h1>問題一覧</h1><div class="row"><button data-go="import">一括インポート</button><button class="primary" data-go="edit">＋ 問題登録</button></div></div>${demoBanner()}<form id="list-filters"><label class="section">問題文・タグで検索<input name="search" type="search" placeholder="キーワードを入力" value="${esc(listFilter.search)}"></label><div class="filters">${filterFields(listFilter)}</div></form><div class="row between"><span class="muted">${filtered.length}問 / ${questions.length}問</span></div><div class="panel">${filtered.length?filtered.map(q=>{const s=stat(q);return `<div class="question-row"><div class="question-row-summary"><span class="badge rank">${q.rank} ${q.rank==='A'?'頻出':q.rank==='B'?'標準':'低頻度'}</span><span class="muted">${'★'.repeat(q.difficulty)}</span>${q.assets.length?'<span class="badge">画像あり</span>':''}${s.weak?'<span class="badge weak">苦手</span>':''}${s.studied?'<span class="badge green">学習済み</span>':''}${s.rate!==null?`<span>${rateLabel(s)}</span>`:''}</div><div class="question-row-text">${q.question_number!=null&&q.question_number!==''?`問${esc(q.question_number)} `:''}${esc(q.text?.trim()||'画像の問題')}</div><div class="question-row-actions"><button class="primary small-button solve-button-gap" data-solve="${q.id}">解く</button>${!demo?`<button class="small-button" data-edit="${q.id}">編集</button><button class="small-button" data-delete="${q.id}">削除</button>`:''}</div></div>`;}).join(''):'<div class="empty"><strong>該当する問題はありません</strong>絞り込みを変更するか、新しい問題を登録してください。</div>'}</div>`;const rankSelect=$('#list-filters select[name="rank"]');if(rankSelect){const syncButton=document.createElement('button');syncButton.type='button';syncButton.className='quiet list-sync';syncButton.dataset.action='sync';syncButton.textContent='↻ 再取得';rankSelect.closest('label')?.insertAdjacentElement('afterend',syncButton);}}
function setup(mode=currentMode){currentMode=mode;const n=filterQuestions(questions,studyFilter,history).length;app.innerHTML=`<div class="eyebrow">${mode==='stamina'?'🔥 STAMINA MODE':'STUDY SETTINGS'}</div><h1>${modes[mode]}の出題設定</h1><p class="muted">条件を組み合わせて、いま学びたい問題を選びましょう。</p>${demoBanner()}<form id="study-filters" class="panel section"><div class="filters">${filterFields(studyFilter,true)}</div><div class="row between"><p><strong id="match-count">${n}</strong>問が条件に一致</p><button class="primary" type="submit" ${!n?'disabled':''}>${modes[mode]}をはじめる →</button></div>${mode==='stamina'?'<p class="muted">一周ごとに間違えた問題だけを再出題。全問正解するまで続きます。途中終了もできます。</p>':''}</form>`;}
function newQuestion(bookId=selectedBook,number){const b=books.find(b=>b.id===bookId),choices=Array.from({length:b?.choice_count||5},(_,position)=>({id:uuid(),text:'',position}));return {id:uuid(),question_book_id:b?.id||'',question_number:number||Math.max(0,...questions.filter(q=>q.question_book_id===bookId).map(q=>q.question_number||0))+1,category:'',genre:b?.genre||'',text:'',choices,correct_choice_id:null,answer_text:'',ocr_text:'',explanation:'',mnemonic:'',memo:'',rank:'B',difficulty:1,format:'text',shuffle:true,tags:[],assets:[],revision:0};}
function bookLabel(b){return [b.name,b.year?b.year+'年':'',b.exam_round,b.genre].filter(Boolean).join(' / ');}
function booksPage(editId){const b=books.find(x=>x.id===editId)||{};app.innerHTML=`<div class="row between"><h1>問題集管理</h1><button data-go="import">一括インポート</button></div><p>先に問題集を登録し、使う問題集を選んで問題を作成します。</p>${demoBanner()}<section class="panel"><h2>${b.id?'問題集を編集':'新しい問題集'}</h2><form id="book-form" class="form-grid"><input type="hidden" name="id" value="${esc(b.id)}"><label class="wide">タイトル<input name="name" required maxlength="120" value="${esc(b.name)}" placeholder="例：第一種衛生管理者"></label><label>年<input name="year" type="number" min="1900" max="2200" value="${b.year||''}" placeholder="2026"></label><label>回・試験名<input name="exam_round" maxlength="80" value="${esc(b.exam_round)}" placeholder="例：上期・第1回"></label><label>ジャンル<input name="genre" maxlength="120" value="${esc(b.genre)}" placeholder="労働衛生"></label><label>予定問題数（任意）<input name="expected_count" type="number" min="1" max="10000" value="${b.expected_count||''}" placeholder="試験に合わせて入力"></label><label>標準の選択肢数<select name="choice_count"><option value="5" ${b.choice_count!==4?'selected':''}>5択</option><option value="4" ${b.choice_count===4?'selected':''}>4択</option></select></label><div class="wide"><button class="primary" ${demo?'disabled':''}>${b.id?'変更を保存':'問題集を登録'}</button></div></form></section><h2>登録した問題集</h2><section class="panel">${books.map(x=>`<div class="book"><div class="grow"><strong>${esc(bookLabel(x))}</strong><small>${questions.filter(q=>q.question_book_id===x.id).length}問登録${x.expected_count?' / 予定'+x.expected_count+'問':''} ・ ${x.choice_count||4}択</small></div><button data-create-book="${x.id}">この問題集に問題を作成</button><button data-book-edit="${x.id}">編集</button></div>`).join('')||'<p>問題集はまだありません。</p>'}</section>`;}
function chooseBook(){app.innerHTML=`<h1>問題を作成する問題集を選択</h1><p>年・回を確認して選んでください。問題数は試験ごとに自由に設定できます。</p><section class="panel">${books.map(b=>`<div class="book"><strong class="grow">${esc(bookLabel(b))}</strong><button data-create-book="${b.id}">選択して作成 →</button></div>`).join('')}<button data-go="books">問題集を管理・新規登録</button></section>`;}
function readEditor(){const form=$('#question-form');if(!form||!editor)return;const f=new FormData(form);for(const k of ['question_book_id','category','genre','text','explanation','mnemonic','memo','rank','format','correct_choice_id','answer_text','ocr_text'])editor[k]=f.get(k);editor.difficulty=+f.get('difficulty');editor.shuffle=f.has('shuffle');editor.tags=String(f.get('tags')||'').split(/[,、\n]/).map(s=>s.trim()).filter(Boolean);editor.choices=editor.choices.map(c=>({...c,text:f.get('choice-'+c.id)||''}));editor.question_number=Number(f.get('question_number'))||null;}
async function keepDraft(){if(demo||!editor)return;readEditor();await localPut(tempKey('draft'),editor);}
function releaseUrls(){objectUrls.forEach(URL.revokeObjectURL);objectUrls=[];}
function assetUrl(a){if(a.file){const u=URL.createObjectURL(a.file);objectUrls.push(u);return u;}return a.url;}
async function edit(id){if(demo){app.innerHTML=`<h1>自分の問題を登録</h1><div class="panel section"><h2>アカウントで同期</h2><p>iPadで登録した問題を、iPhoneでも学べます。問題の登録・編集にはログインしてください。</p><button class="primary" data-go="settings">ログイン / 設定へ</button></div>`;return;}if(!id&&!selectedBook){chooseBook();return;}const generation=authGeneration;const draft=await localGet(tempKey('draft'));if(generation!==authGeneration)return;if(id){const q=questions.find(q=>q.id===id);if(!q){toast('問題が見つかりません。再取得してください。',true);location.hash='#list';return;}editor=structuredClone(q);}else editor=newQuestion();if(draft){if(confirm('この端末に入力途中の下書きがあります。先に下書きを復元しますか？'))editor=draft;else if(!confirm('既存の下書きを破棄して、この問題を編集しますか？')){editor=null;location.hash='#list';return;}else await localPut(tempKey('draft'),undefined);}dirty=!!draft;renderEditor();}
function renderEditor(){releaseUrls();const q=editor;app.innerHTML=`<div class="row between"><h1>${q.revision?'問題を編集':'問題を登録'}</h1><span class="muted">${dirty?'下書きあり':'クラウドへ保存'}</span></div><p class="muted">問題文の代わりに画像だけでも登録できます。写真を読み取った後、内容と正解を確認して登録します。</p><form id="question-form" class="section"><div class="panel form-grid"><label class="wide">選択中の問題集<strong>${esc(bookLabel(books.find(b=>b.id===q.question_book_id)||{name:'未選択'}))}</strong><input type="hidden" name="question_book_id" value="${esc(q.question_book_id)}"></label><label>問題番号<input name="question_number" type="number" min="1" max="10000" value="${q.question_number||''}" required></label><label>選択肢数<select id="choice-count"><option value="4" ${q.choices.length===4?'selected':''}>4択</option><option value="5" ${q.choices.length===5?'selected':''}>5択</option></select></label><label>大分類<input name="category" list="categories" value="${esc(q.category)}"></label><label>ジャンル<input name="genre" list="genres" value="${esc(q.genre)}"></label><datalist id="categories">${unique('category').map(n=>`<option value="${esc(n)}">`).join('')}</datalist><datalist id="genres">${unique('genre').map(n=>`<option value="${esc(n)}">`).join('')}</datalist>${photoInputs(q)}<label class="wide">問題文<textarea name="text" rows="4" placeholder="問題文を入力（画像がある場合は空欄でも可）">${esc(q.text)}</textarea></label></div><div class="panel"><h2>解答欄・${q.choices.length}つの選択肢</h2><p class="muted">正解の選択肢にチェックを付けてください。</p><div class="choices">${q.choices.map((c,i)=>`<div class="choice-edit"><input aria-label="選択肢${i+1}を正解にする" type="radio" name="correct_choice_id" value="${c.id}" ${q.correct_choice_id===c.id?'checked':''} required><span>${i+1}</span><textarea aria-label="選択肢${i+1}" name="choice-${c.id}" required rows="2">${esc(c.text)}</textarea></div>`).join('')}</div><label class="check"><input type="checkbox" name="shuffle" ${q.shuffle?'checked':''}>選択肢の表示順をシャッフルする</label><small>「上記の1と2」など番号を参照する問題ではOFFにしてください。</small></div><div class="panel form-grid"><h2 class="wide">答え・ヒント</h2>${[['answer_text','解答の読み取り・補足'],['explanation','解説'],['mnemonic','覚え方'],['memo','自分メモ']].map(([k,t])=>`<label class="wide">${t}<textarea name="${k}" rows="3">${esc(q[k])}</textarea></label>`).join('')}<label>頻出ランク<select name="rank">${options([['A','A：頻出'],['B','B：標準'],['C','C：低頻度']],q.rank).replace('<option value="">すべて</option>','')}</select></label><label>難易度<select name="difficulty">${[1,2,3,4,5].map(n=>`<option value="${n}" ${n===q.difficulty?'selected':''}>${'★'.repeat(n)}</option>`).join('')}</select></label><label>問題形式<select name="format">${options([['text','文章のみ'],['diagram','図あり'],['table','表あり'],['image','画像中心']],q.format).replace('<option value="">すべて</option>','')}</select></label><label>タグ（カンマ区切り）<input name="tags" value="${esc(q.tags.join(', '))}" placeholder="計算, 暗記, 法令"></label></div><p class="muted" id="draft-state">入力途中の内容は、この端末に一時保存します。クラウドへの保存は下のボタンを押してください。</p><div class="actions">${q.revision?'<button type="button" class="danger" data-action="delete">問題を削除</button>':''}<button type="button" data-action="discard">下書きを破棄</button><button type="submit" name="save-next" value="yes" class="primary">登録して次の問題へ →</button><button type="submit">${q.revision?'更新して保存':'クラウドに保存'}</button></div></form>`;}
async function saveEditor(next=false){if(saving)return;clearTimeout(draftTimer);saving=true;showSavingDialog();let q;try{readEditor();q=editor;const uid=user.id;if(!q.text.trim()&&!q.assets.length)throw Error('問題文または画像が必要です');if(q.choices.some(c=>!c.text.trim()))throw Error('すべての選択肢を入力してください');await keepDraft();$('#question-form button[type=submit]').disabled=true;if(!q.question_book_id)throw Error('問題集を選択してください');if(!q.choices.some(c=>c.id===q.correct_choice_id))throw Error('正解を確認して選択してください');if(questions.some(x=>x.id!==q.id&&x.question_book_id===q.question_book_id&&x.question_number===q.question_number))throw Error('この問題番号は登録済みです。番号を変更するか既存の問題を編集してください');for(const [i,a] of q.assets.entries()){a.display_order=i;if(a.file&&!a.storage_path){const plan=uploadPlan(a.file.type,a.file.size),upload=plan==='asis'?a.file:await normalizeImage(a.file);const ext=plan==='asis'?({'image/jpeg':'jpg','image/png':'png','image/webp':'webp','image/gif':'gif'})[a.file.type]:'jpg';const path=`${uid}/${q.id}/${uuid()}.${ext}`;await repo.upload(path,upload);a.storage_path=path;await localPut(tempKey('draft'),q);}}
const old=questions.find(x=>x.id===q.id);await repo.save({...q,assets:q.assets.map(({id,asset_type,storage_path,display_order})=>({id,asset_type,storage_path,display_order}))});await localPut(tempKey('draft'),undefined);dirty=false;editor=null;const removed=old?.assets.filter(a=>!q.assets.some(x=>x.storage_path===a.storage_path)).map(a=>a.storage_path)||[];let warning='';try{await repo.removeAssets(removed);}catch{warning='（未参照画像の削除は未完了です）';}await sync(false);toast('クラウドに保存しました。'+warning);if(next){selectedBook=q.question_book_id;editor=newQuestion(selectedBook,(q.question_number||0)+1);renderEditor();window.scrollTo(0,0);}else location.hash='#list';}catch(e){fail(e);if(editor)await localPut(tempKey('draft'),editor).catch(()=>{});}finally{hideSavingDialog();saving=false;const b=$('#question-form button[type=submit]');if(b)b.disabled=false;}}
async function start(mode){if(session&&!session.finished&&!confirm('現在の学習を終了して、新しく始めますか？'))return;const f=studyFilter;let selected=filterQuestions(questions,f,history);if(f.random!==false){const {shuffle}=await import('./engine.js');selected=shuffle(selected);}selected=selected.slice(0,f.count==='all'?selected.length:+(f.count||10));if(!selected.length){toast('条件に合う問題がありません。',true);return;}session=createSession(structuredClone(selected),mode);enterQuestion(session);location.hash='#study';renderStudy();await markViewed();}
async function solveQuestion(q){session=createSession([structuredClone(q)],'learning');enterQuestion(session);location.hash='#study';renderStudy();await markViewed();}
function images(q){return `<div class="images">${q.assets.filter(a=>a.asset_type!=='explanation').map((a,i)=>`<button data-image="${esc(a.url)}" aria-label="問題画像${i+1}を拡大"><img src="${esc(a.url)}" alt="問題画像 ${i+1}"></button>`).join('')}</div>`;}
function explanations(q){return [['answer_text','解答の読み取り・補足'],['explanation','解説'],['mnemonic','覚え方'],['memo','自分メモ']].map(([k,t])=>`<section class="explanation"><h3>${t}</h3><p>${esc(q[k]||'未登録')}</p></section>`).join('');}
function renderStudy(){if(!session){location.hash='#home';return;}const s=session;if(s.finished){result();return;}const q=s.queue[s.index],show=!!s.currentAnswer||s.revealedFor===q.id;app.innerHTML=`<div class="row between"><span class="eyebrow ${s.mode==='stamina'?'stamina-heading':''}">${s.mode==='stamina'?'🔥 STAMINA MODE ・ '+s.round+'周目':modes[s.mode]}</span><button class="quiet" data-action="end">学習を終了</button></div><div class="row between"><span>${esc(bookName(q.question_book_id))}</span><strong>${s.mode==='stamina'?'残り '+(s.queue.length-s.index)+'問 ・ ':''}${s.index+1} / ${s.queue.length}</strong></div><div class="progress"><i style="width:${100*(s.index+1)/s.queue.length}%"></i></div><section class="panel"><div class="row"><span class="badge rank">頻出 ${q.rank}</span><span class="muted">${esc(q.genre)}　${'★'.repeat(q.difficulty)}</span>${q.shuffle?'<span class="badge">選択肢シャッフル</span>':''}</div><div class="question-text">${esc(q.text||'画像を見て、正しい選択肢を選んでください。')}</div>${images(q)}<div class="choices">${s.order.map((c,i)=>{const correct=show&&q.correct_choice_id===c.id,wrong=show&&s.currentAnswer?.selected_choice_id===c.id&&!correct;return `<button class="choice ${correct?'correct':wrong?'wrong':''}" data-choice="${c.id}" ${show?'disabled':''}><b>${i+1}</b><span>${correct?'✓ ':wrong?'× ':''}${esc(c.text)}${correct?'　（正解）':''}</span></button>`;}).join('')}</div>${s.currentAnswer?`<div class="feedback ${s.currentAnswer.is_correct?'':'bad'}">${s.currentAnswer.is_correct?'○ 正解':'× 不正解'}</div>`:''}${show?explanations(q)+images({...q,assets:q.assets.filter(a=>a.asset_type==='explanation').map(a=>({...a,asset_type:'question'}))}):''}<div class="actions">${s.mode==='learning'?`<button data-action="previous" ${s.index===0?'disabled':''}>← 前へ</button>${show?'':'<button data-action="reveal">答えを見る</button>'}`:''}<button class="primary" data-action="next" ${show?'':'disabled'}>${s.index===s.queue.length-1?(s.mode==='stamina'&&(s.misses.length||!show)?'次の周へ →':'結果を見る →'):'次の問題へ →'}</button></div></section><div class="sync">${demo?'サンプルの履歴は一時的です':pending.length?'未送信の履歴 '+pending.length+'件':'履歴をクラウドへ保存'}</div>`;}
async function queueEvent(event){if(demo){history.push(event);return;}event.user_id=user.id;pending.push(event);await localPut(tempKey('outbox'),pending);await flushOutbox();}
async function flushOutbox(){if(demo||!repo||outboxBusy||!pending.length)return;outboxBusy=true;const generation=authGeneration,key=tempKey('outbox'),r=repo;try{while(pending.length&&generation===authGeneration){const e=pending[0],saved=await r.answer(e);if(generation!==authGeneration)return;if(!history.some(h=>h.id===saved.id))history.push(saved);pending=pending.filter(h=>h.id!==e.id);await localPut(key,pending);}}catch(e){toast('学習履歴をまだ保存できていません。未送信 '+pending.length+'件をこの端末に保持しています。設定画面で再送できます。\n'+(e.message||e),true);}finally{outboxBusy=false;}}
async function markViewed(){const s=session;if(!s||s.mode!=='learning'||s.finished)return;const q=s.queue[s.index];if(s.views.has(q.id))return;const event={id:uuid(),session_id:s.id,question_id:q.id,mode:'learning',selected_choice_id:null,display_number:null,correct_choice_id:q.correct_choice_id,display_order:s.order.map(c=>c.id),is_correct:null,answered_at:new Date().toISOString()};s.views.add(q.id);await queueEvent(event);}
function result(){const s=session,n=s.initial.length;app.innerHTML=`<div class="eyebrow">${s.mode==='stamina'?'🔥 STAMINA COMPLETE':'SESSION COMPLETE'}</div><h1>${s.mode==='stamina'?'全問攻略、おつかれさま！':s.mode==='learning'?'ひと通り、学びました。':'テストが終わりました。'}</h1><div class="panel section"><div class="result-number">${s.mode==='learning'?s.views.size:s.mode==='stamina'?n:s.firstCorrect}<small> / ${n}</small></div><p class="muted">${s.mode==='learning'?'学習した問題数':s.mode==='stamina'?'最終攻略問題数':'正解した問題数'}</p>${s.mode!=='learning'?`<div class="stats"><div class="stat"><strong>${n}</strong><span>初回問題数</span></div><div class="stat"><strong>${s.firstCorrect}</strong><span>初回正解数</span></div><div class="stat"><strong>${n-s.firstCorrect}</strong><span>初回不正解数</span></div></div><div class="row"><span>総回答数 <b>${s.answers.length}</b></span><span>再挑戦回数 <b>${Math.max(0,s.answers.length-n)}</b>回答</span><span>周回数 <b>${s.round}</b></span></div>`:''}<p class="muted">${demo?'サンプルの学習記録は、この画面を閉じるまで有効です。':pending.length?'未送信の履歴があります。設定画面で再送してください。':'回答履歴をクラウドに保存しました。'}</p><div class="actions"><button data-mode="${s.mode}">もう一度学ぶ</button><button class="primary" data-go="home">ホームへ</button></div></div>`;}
function historyPage(){const all=history.filter(h=>h.mode!=='learning'),p=progressFor(history);app.innerHTML=`<h1>学習履歴</h1>${demoBanner()}<div class="stats"><div class="stat"><strong>${all.length}</strong><span>総回答数</span></div><div class="stat"><strong>${p.rate===null?'—':Math.round(p.rate*100)+'%'}</strong><span>正答率</span></div><div class="stat"><strong>${questions.filter(q=>stat(q).studied).length}</strong><span>ラーニング学習済み</span></div></div><div class="row between"><h2>問題ごとの記録</h2><button class="quiet" data-action="sync">↻ 再取得</button></div><div class="panel">${questions.filter(q=>history.some(h=>h.question_id===q.id)).map(q=>{const s=stat(q);return `<div class="history-item"><div class="row">${s.weak?'<span class="badge weak">苦手</span>':''}${s.studied?'<span class="badge green">学習済み</span>':''}<strong>${esc(q.text.slice(0,70)||'画像の問題')}</strong></div><p>回答 ${s.total}回　正解 ${s.correct}回　不正解 ${s.wrong}回</p><small>正答率 ${s.rate===null?'—':Math.round(s.rate*100)+'%'}　連続正解 ${s.streak}回　${s.last?'最終回答 '+new Date(s.last).toLocaleString('ja-JP'):''}</small></div>`;}).join('')||'<div class="empty"><strong>これから積み重ねていきましょう</strong>学習すると、ここに記録されます。</div>'}</div><h2>最近の回答</h2><div class="panel">${[...history].sort((a,b)=>b.answered_at.localeCompare(a.answered_at)).slice(0,30).map(h=>`<div class="history-item"><span class="badge ${h.mode==='learning'||h.is_correct?'green':'weak'}">${h.mode==='learning'?'閲覧':h.is_correct?'○ 正解':'× 不正解'}</span> <small>${modes[h.mode]} · ${new Date(h.answered_at).toLocaleString('ja-JP')}</small><p>${esc(questions.find(q=>q.id===h.question_id)?.text.slice(0,80)||'画像の問題')}</p>${h.display_number?'<small>選択した表示番号：'+h.display_number+'</small>':''}</div>`).join('')||'<p class="muted">まだ記録がありません。</p>'}</div>`;}
function getConfig(){return window.YONSTUDY_CONFIG||{};}
function authMessage(error){return error?.code==='invalid_credentials'||/invalid login credentials/i.test(error?.message||'')?'メールアドレスまたはパスワードが違います':'ログインできませんでした。しばらくしてからもう一度お試しください';}
let authBusy=false,authMode='login',authEmail='',recovery=false;
async function submitAuth(form,signup){
 if(authBusy)return;
 const fields=new FormData(form),email=String(fields.get('email')||'').trim(),password=String(fields.get('password')||'');
 authBusy=true;form.querySelectorAll('button').forEach(b=>b.disabled=true);
 try{
  if(!client)await initAuth();
  if(!client)throw Error('Auth unavailable');
  const result=signup?await client.auth.signUp({email,password,options:{emailRedirectTo:AUTH_REDIRECT}}):await client.auth.signInWithPassword({email,password});
  if(result.error)throw result.error;
  form.reset();
  if(signup){toast('確認メールを送りました。メール内のリンクを開いてから、ログインしてください');}
  else {await changeUser(result.data.user);toast('ログインしました');}
 }catch(error){toast(authMessage(error),true);}
 finally{authBusy=false;form.querySelectorAll('button').forEach(b=>b.disabled=false);}
}
function accountCard(){if(recovery)return `<p>新しいパスワードを設定してください。</p><form id="recovery-form" class="form-grid"><label class="wide">新しいパスワード<input type="password" name="password" autocomplete="new-password" required></label><div class="wide"><button type="submit" class="primary">パスワードを変更</button></div></form>`;if(user)return `<p><strong>${esc(user.email||'ユーザー')}</strong>でログイン中</p><p class="muted">同じアカウントでログインしたiPhone・iPadでデータを共有できます。</p><div class="row"><button data-action="sync">↻ クラウドから再取得</button><button data-action="logout">ログアウト</button></div><p class="sync">${syncLabel()}</p>`;if(authMode==='reset')return `<p>登録したメールアドレスへ再設定用のリンクを送ります。</p><form id="reset-form" class="form-grid"><label class="wide">メールアドレス<input type="email" name="email" autocomplete="username" value="${esc(authEmail)}" required></label><div class="wide"><button type="submit" class="primary">再設定メールを送る</button></div><div class="wide"><small><a href="#" data-auth-mode="login">ログインに戻る</a></small></div></form>`;return `<p>メールアドレスでログインして、問題と学習履歴を保存します。</p><form id="auth-form" class="form-grid"><label class="wide">メールアドレス<input type="email" name="email" autocomplete="username" value="${esc(authEmail)}" required></label><label class="wide">パスワード<input type="password" name="password" autocomplete="${authMode==='signup'?'new-password':'current-password'}" required></label><div class="wide"><button type="submit" class="primary" name="${authMode}">${authMode==='signup'?'新規登録':'ログイン'}</button></div><div class="wide"><small><a href="#" data-auth-mode="${authMode==='signup'?'login':'signup'}">${authMode==='signup'?'ログインはこちら':'新規登録はこちら'}</a></small></div>${authMode==='login'?'<div class="wide"><small><a href="#" data-auth-mode="reset">パスワードを忘れた方</a></small></div>':''}</form><p class="muted">Google ログインは現在使えません。メールアドレスでログインしてください</p>`;}
function settings(){app.innerHTML=`<h1>設定</h1><section class="panel section"><h2>アカウント</h2>${accountCard()}</section><section class="panel"><h2>アプリ設定</h2><label class="check"><input id="sfx-setting" type="checkbox" ${sfxEnabled?'checked':''}>効果音</label><p><strong>バージョン</strong> ${APP_VERSION}</p><button data-action="check-update">アップデートを確認</button></section><section class="panel"><h2>未送信の学習履歴</h2><p>${pending.length}件</p><p class="muted">通信失敗時の回答を、この端末に一時保存しています。</p><button data-action="retry" ${!pending.length?'disabled':''}>履歴を再送する</button></section><section class="panel"><h2>iPhone・iPadで使う</h2><p>Safariでこのアプリを開き、共有メニューから「ホーム画面に追加」を選びます。各端末で同じアカウントにログインしてください。</p><p class="muted">学習・保存には通信が必要です。入力途中の下書きは、この端末だけに残ります。ほかの端末へは「クラウドに保存」を押すと反映されます。</p></section><section class="panel"><h2>サンプル問題</h2><p>算数・IT基礎のオリジナル8問（図あり1問）を追加できます。</p><button data-action="seed" ${!user?'disabled':''}>サンプルを自分の問題集に追加</button></section>`;}
function switchAuthMode(form,mode){authEmail=String(form?.querySelector('[name="email"]')?.value||authEmail);authMode=mode;settings();}
async function resetPassword(form){if(authBusy)return;const email=String(new FormData(form).get('email')||'').trim();authEmail=email;authBusy=true;form.querySelectorAll('button').forEach(b=>b.disabled=true);try{if(!client)await initAuth();if(!client)throw Error('Auth unavailable');const {error}=await client.auth.resetPasswordForEmail(email,{redirectTo:AUTH_REDIRECT});if(error)throw error;toast('パスワード再設定メールを送りました');}catch(error){toast('再設定メールを送れませんでした。メールアドレスと通信環境を確認してください',true);}finally{authBusy=false;form.querySelectorAll('button').forEach(b=>b.disabled=false);}}
async function updatePassword(form){if(authBusy)return;const password=String(new FormData(form).get('password')||'');authBusy=true;form.querySelectorAll('button').forEach(b=>b.disabled=true);try{const {error}=await client.auth.updateUser({password});if(error)throw error;recovery=false;toast('パスワードを変更しました');settings();}catch(error){toast('パスワードを変更できませんでした。しばらくしてからもう一度お試しください',true);}finally{authBusy=false;form.querySelectorAll('button').forEach(b=>b.disabled=false);}}
function withTimeout(promise,ms){return new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('通信がタイムアウトしました')),ms);Promise.resolve(promise).then(value=>{clearTimeout(timer);resolve(value);},error=>{clearTimeout(timer);reject(error);});});}
async function sync(render=true){if(demo||!repo||syncing)return;syncing=true;const generation=authGeneration,r=repo;try{await withTimeout(flushOutbox(),15000);const data=await withTimeout(r.load(),15000);if(generation!==authGeneration)return;books=data.books;questions=data.questions;history=data.history;loaded=true;lastSync=new Date();if(session&&!session.finished){for(const q of session.queue){const fresh=questions.find(x=>x.id===q.id);if(fresh)for(const a of q.assets){a.url=fresh.assets.find(x=>x.id===a.id)?.url||a.url;}}}if(render&&!['#edit','#study','#import'].some(p=>location.hash.startsWith(p)))route();}catch(e){toast('クラウドから読み込めませんでした。表示中のデータや下書きは残しています。通信環境を確認してください。\n'+(e.message||e),true);}finally{syncing=false;}}
async function initAuth(){const c=getConfig();if(!c.supabaseUrl||!c.supabaseKey)return;const {createClient}=await import('./supabase.js');client=createClient(c.supabaseUrl,c.supabaseKey,{db:{schema:'yonstudy'},auth:{flowType:'pkce',persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,storageKey:'yonstudy-auth-'+new URL(c.supabaseUrl).hostname}});repo=createRepository(client);client.auth.onAuthStateChange((event,s)=>{if(event==='PASSWORD_RECOVERY'){recovery=true;location.hash='#settings';}setTimeout(()=>changeUser(s?.user||null).catch(fail),0);});const {data,error}=await client.auth.getSession();if(error)throw error;await changeUser(data.session?.user||null);}
async function changeUser(next){if(user?.id===next?.id)return;authGeneration++;bulk.accountChanged();user=next;session=null;editor=null;dirty=false;pending=[];lastSync=null;releaseUrls();if(next){demo=false;loaded=false;books=[];questions=[];history=[];pending=await localGet(tempKey('outbox'))||[];await sync(false);}else setDemo();route();}
async function seed(){if(saving)return;saving=true;const key=tempKey('sample-import');try{let job=await localGet(key);if(!job){if(books.some(b=>b.name==='はじめての4択')){toast('サンプル問題集はすでにあります。');return;}const sample=samples();job={...sample,next:0};await localPut(key,job);}let b=books.find(b=>b.id===job.book.id);if(!b){b=await repo.book(job.book,user.id);books.push(b);}for(;job.next<job.questions.length;job.next++){const q=job.questions[job.next];if(!questions.some(x=>x.id===q.id)){for(const a of q.assets){if(!a.storage_path){const response=await fetch(a.url);const blob=await svgToPng(await response.text());const path=`${user.id}/${q.id}/${uuid()}.png`;await repo.upload(path,blob);a.storage_path=path;await localPut(key,job);}}await repo.save(q);}await localPut(key,{...job,next:job.next+1});}await localPut(key,undefined);await sync(false);toast('サンプル8問を追加しました。');route();}catch(e){fail(e);await sync(false);}finally{saving=false;}}
async function svgToPng(svg){return new Promise((resolve,reject)=>{const img=new Image(),url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));img.onload=()=>{const canvas=document.createElement('canvas');canvas.width=480;canvas.height=300;canvas.getContext('2d').drawImage(img,0,0);URL.revokeObjectURL(url);canvas.toBlob(b=>b?resolve(b):reject(Error('画像を変換できませんでした')),'image/png');};img.onerror=reject;img.src=url;});}
function route(){nav();const [path,id]=location.hash.slice(1).split('/');if(path==='edit'){if(editor){renderEditor();return;}edit(id).catch(fail);return;}if(path==='import'){bulk.show().catch(fail);return;}if(path==='books')booksPage(id);else if(path==='list')list();else if(path==='settings')settings();else if(path==='history')historyPage();else if(path==='setup')setup(modes[id]?id:currentMode);else if(path==='study')renderStudy();else home();}
document.addEventListener('click',e=>{if(saving&&e.target.closest('a,button')){e.preventDefault();e.stopImmediatePropagation();}},true);
window.addEventListener('hashchange',()=>{bulk.leave();clearTimeout(draftTimer);if(!location.hash.startsWith('#edit')&&editor){keepDraft().catch(fail);editor=null;dirty=false;releaseUrls();}route();window.scrollTo(0,0);});
window.addEventListener('beforeunload',e=>{if(dirty||saving||pending.length){e.preventDefault();e.returnValue='';}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')sync();else if(editor)keepDraft().catch(fail);});window.addEventListener('pageshow',()=>sync());window.addEventListener('online',()=>sync());
$('#account').onclick=()=>location.hash='#settings';$('#close-image').onclick=()=>$('#lightbox').close();
app.addEventListener('click',e=>{const link=e.target.closest('[data-auth-mode]');if(!link)return;e.preventDefault();e.stopImmediatePropagation();switchAuthMode(link.closest('form'),link.dataset.authMode);});
app.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;try{if(b.dataset.solve){e.stopPropagation();const q=questions.find(q=>q.id===b.dataset.solve);if(q)await solveQuestion(q);return;}if(b.dataset.delete){e.stopPropagation();const q=questions.find(q=>q.id===b.dataset.delete);if(q&&confirm('この問題を削除しますか？')){const warning=await repo.remove(q);questions=questions.filter(x=>x.id!==q.id);list();toast('問題を削除しました。'+(warning||''));}return;}if(b.dataset.bookEdit){location.hash='#books/'+b.dataset.bookEdit;return;}if(b.dataset.createBook){selectedBook=b.dataset.createBook;editor=null;if(location.hash==='#edit')await edit();else location.hash='#edit';return;}if(b.dataset.go){location.hash='#'+b.dataset.go;return;}if(b.dataset.mode){location.hash='#setup/'+b.dataset.mode;return;}if(b.dataset.book){listFilter={book:b.dataset.book};location.hash='#list';return;}if(b.dataset.edit){e.stopPropagation();editor=null;location.hash='#edit/'+b.dataset.edit;return;}if(b.dataset.image){const dialog=$('#lightbox');dialog.querySelector('img').src=b.dataset.image;dialog.showModal();return;}if(b.dataset.removeAsset){readEditor();editor.assets=editor.assets.filter(a=>a.id!==b.dataset.removeAsset);dirty=true;await localPut(tempKey('draft'),editor);renderEditor();return;}if(b.dataset.choice){const ev=answer(session,b.dataset.choice);if(ev){await playAnswerSound(ev.is_correct);renderStudy();await queueEvent(ev);}return;}switch(b.dataset.action){case 'split-text':readEditor();applyScan(splitScanText(editor.ocr_text));break;case 'scan':await scanPhotos();break;case 'sync':await sync();break;case 'check-update':{const response=await fetch(`app.js?t=${Date.now()}`,{cache:'no-store'});if(!response.ok)throw Error('update check failed');const text=await response.text(),served=text.match(/const APP_VERSION\s*=\s*['"]([^'"]+)['"]/i)?.[1];if(!served)throw Error('version not found');if(served!==APP_VERSION){toast('新しいバージョンがあります。再読み込みします');location.reload();}else toast('最新のバージョンです');break;}case 'weak':studyFilter={weak:true};location.hash='#setup/test';break;case 'reveal':{const q=session?.queue[session.index];if(session?.mode==='learning'&&q){session.revealedFor=q.id;renderStudy();}}break;case 'next':advance(session);renderStudy();window.scrollTo(0,0);await markViewed();if(session.finished)await sync(false);break;case 'previous':if(session.index>0){session.index--;enterQuestion(session);renderStudy();window.scrollTo(0,0);await markViewed();}break;case 'end':if(confirm('学習を途中で終了しますか？ここまでの回答は履歴に残ります。')){session=null;await sync(false);location.hash='#home';}break;case 'logout':await flushOutbox();if(pending.length&&!confirm('未送信の履歴はこの端末に残ります。同じアカウントで再ログインすると再送できます。ログアウトしますか？'))return;{const {error}=await client.auth.signOut({scope:'local'});if(error){toast(authMessage(error),true);return;}}await changeUser(null);break;case 'retry':await flushOutbox();settings();if(!pending.length)toast('未送信の履歴はありません。');break;case 'seed':await seed();break;case 'delete':clearTimeout(draftTimer);if(confirm('この問題と回答履歴を削除します。元に戻せません。削除しますか？')){b.disabled=true;const warn=await repo.remove(editor);await localPut(tempKey('draft'),undefined);editor=null;dirty=false;await sync(false);toast(warn||'問題を削除しました。',!!warn);location.hash='#list';}break;case 'discard':clearTimeout(draftTimer);if(confirm('この端末の下書きを破棄しますか？')){await localPut(tempKey('draft'),undefined);editor=null;dirty=false;location.hash='#list';}break;}}catch(err){if(b.dataset.action==='check-update')toast('アップデートを確認できませんでした',true);else fail(err);}});
app.addEventListener('input',e=>{if(e.target.closest('#question-form')){dirty=true;clearTimeout(draftTimer);readEditor();draftTimer=setTimeout(()=>keepDraft().then(()=>{const t=$('#draft-state');if(t)t.textContent='この端末に下書きを保存しました。クラウドへは未保存です。';}).catch(fail),350);}});
app.addEventListener('change',async e=>{try{if(e.target.id==='sfx-setting'){sfxEnabled=e.target.checked;localStorage.setItem(SFX_KEY,String(sfxEnabled));}if(e.target.closest('#list-filters')){listFilter=readFilters($('#list-filters'));list();}if(e.target.closest('#study-filters')){studyFilter=readFilters($('#study-filters'));const n=filterQuestions(questions,studyFilter,history).length;$('#match-count').textContent=n;$('#study-filters button[type=submit]').disabled=!n;}if(e.target.getAttribute('id')==='choice-count'){readEditor();if(+e.target.value===4&&editor.choices[4]?.text&&!confirm('5つ目の選択肢を削除しますか？')){renderEditor();return;}editor=resizeChoices(editor,+e.target.value,uuid);dirty=true;await localPut(tempKey('draft'),editor);renderEditor();}if(['image-files','answer-files'].includes(e.target.id)){readEditor();for(const file of e.target.files){if(!['image/jpeg','image/png','image/webp','image/gif'].includes(file.type)||file.size>10485760)throw Error('画像はJPEG・PNG・WebP・GIFで10MB以下にしてください');editor.assets.push({id:uuid(),asset_type:e.target.getAttribute('id')==='answer-files'?'explanation':'question',file,display_order:editor.assets.length});}dirty=true;await localPut(tempKey('draft'),editor);renderEditor();}}catch(err){fail(err);}});
app.addEventListener('submit',async e=>{e.preventDefault();if(e.target.id==='auth-form'){authEmail=String(new FormData(e.target).get('email')||'').trim();await submitAuth(e.target,e.submitter?.name==='signup');return;}if(e.target.id==='reset-form'){await resetPassword(e.target);return;}if(e.target.id==='recovery-form'){await updatePassword(e.target);return;}try{if(e.target.getAttribute('id')==='book-form'){if(demo)throw Error('ログインしてください');const f=Object.fromEntries(new FormData(e.target));const b={id:f.id||uuid(),name:f.name.trim(),year:f.year?+f.year:null,exam_round:f.exam_round.trim(),genre:f.genre.trim(),expected_count:f.expected_count?+f.expected_count:null,choice_count:+f.choice_count};await repo.saveBook(b,user.id,!!f.id);await sync(false);toast('問題集を保存しました');if(location.hash==='#books')booksPage();else location.hash='#books';}if(e.target.getAttribute('id')==='question-form')await saveEditor(e.submitter?.name==='save-next');if(e.target.getAttribute('id')==='study-filters'){studyFilter=readFilters(e.target);await start(currentMode);}if(e.target.getAttribute('id')==='list-filters'){listFilter=readFilters(e.target);list();}}catch(err){fail(err);}});
// WebMCPは画面と同じ絞り込み関数で問題数だけを返す。本文の外部公開はしない。
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'count_study_questions',title:'出題条件に合う問題数',description:'現在のユーザーの読み込み済み問題について、問題集と苦手条件に合う問題数を返す。',inputSchema:{type:'object',properties:{bookId:{type:'string'},weakOnly:{type:'boolean'}},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['bookId','weakOnly'].includes(k))||('bookId'in input&&typeof input.bookId!=='string')||('weakOnly'in input&&typeof input.weakOnly!=='boolean'))throw Error('条件が不正です');return {count:filterQuestions(questions,{book:input.bookId,weak:input.weakOnly},history).length,sample:demo};}})).catch(()=>{});}catch{}}
const authError=new URLSearchParams(location.search).get('error')||new URLSearchParams(location.hash.slice(1)).get('error');if(authError){window.history.replaceState(null,'',location.pathname+'#settings');toast(authMessage(),true);}setDemo();route();initAuth().catch(e=>toast(authMessage(e),true));

function photoInputs(q){return `<div class="wide"><h2>1. 問題・解答の写真</h2><p class="muted">1問分を順番に追加してください。長い問題は何枚に分かれていても構いません。解答写真は答え合わせ後だけ表示します。</p>${[['question','問題の写真','image-files'],['explanation','解答・解説の写真','answer-files']].map(([role,label,id])=>`<section class="photo-group"><label>${label}（複数可）<input type="file" id="${id}" accept="image/jpeg,image/png,image/webp,image/gif" multiple><small>JPEG・PNG・WebP・GIF、各10MB以下。追加選択もできます。</small></label><div class="images">${q.assets.filter(a=>(a.asset_type==='explanation'?'explanation':'question')===role).map((a,i)=>{const url=assetUrl(a);return `<div class="image-item"><button type="button" data-image="${esc(url)}"><img src="${esc(url)}" alt="${label} ${i+1}"></button><small>${label} ${i+1}</small><button class="quiet danger" type="button" data-remove-asset="${a.id}">この画像を外す</button></div>`;}).join('')}</div></section>`).join('')}<button type="button" data-action="scan" ${q.assets.length&&window.YONSTUDY_CONFIG?.ocrEnabled?'':'disabled'}>${window.YONSTUDY_CONFIG?.ocrEnabled?'写真を読み取って振り分ける':'写真の自動読み取り：準備中'}</button><p class="muted">読み取り時に写真をOpenAIへ送信します。現在はAPI未接続です。写真の保存と、下の欄に貼り付けたテキストの振り分けは使えます。読み取りは下書きです。正解・誤字・振り分けを必ず確認してください。</p><details><summary>読み取り全文・テキストからの振り分け</summary><label>読み取りテキスト<textarea name="ocr_text" rows="8" placeholder="問題、(1)〜(5)、解答、解説などの見出しで大まかに分けます。">${esc(q.ocr_text)}</textarea></label><button type="button" data-action="split-text">このテキストを振り分ける</button></details><h2>2. 内容を確認・修正</h2></div>`;}
function applyScan(r){if(!editor)return;const q=editor;if(r.text)q.text=r.text;if(r.choices?.length){const count=r.choices.length>4?5:4;editor=resizeChoices(q,count,uuid);editor.choices.forEach((c,i)=>c.text=r.choices[i]||'');editor.correct_choice_id=null;}if(r.answer_text)editor.answer_text=r.answer_text;if(r.explanation)editor.explanation=r.explanation;if(r.correctNumber&&editor.choices[r.correctNumber-1])editor.correct_choice_id=editor.choices[r.correctNumber-1].id;editor.ocr_text=r.raw||editor.ocr_text;dirty=true;localPut(tempKey('draft'),editor).catch(fail);renderEditor();toast('下書きへ振り分けました。元の写真と見比べて、正解・誤字・振り分けを確認してください。');}
async function scanImageParts(a){const blob=a.file||await fetch(a.url).then(r=>{if(!r.ok)throw Error('画像を取得できません。再取得してください');return r.blob();});const bitmap=await createImageBitmap(blob);try{const scale=Math.min(1,1600/bitmap.width),width=Math.round(bitmap.width*scale),height=Math.round(bitmap.height*scale),parts=[];for(let y=0;y<height;y+=2100){const h=Math.min(2200,height-y),canvas=document.createElement('canvas');canvas.width=width;canvas.height=h;canvas.getContext('2d').drawImage(bitmap,0,y/scale,bitmap.width,h/scale,0,0,width,h);parts.push(canvas.toDataURL('image/jpeg',.9));if(y+h>=height)break;}return parts;}finally{bitmap.close();}}
async function scanPhotos(){if(saving||!window.YONSTUDY_CONFIG?.ocrEnabled)return;readEditor();if(!editor.assets.length)return;if(!confirm('この問題の写真をOpenAIへ送信して読み取ります。API利用料が発生します。入力済みの問題・解答・解説欄は読み取り結果で置き換わることがあります。続けますか？'))return;await keepDraft();saving=true;const q=editor;const button=app.querySelector('[data-action=scan]');app.querySelectorAll('#question-form input,#question-form textarea,#question-form select,#question-form button').forEach(x=>x.disabled=true);let raw=q.ocr_text||'';try{const parts=[];for(const a of q.assets){for(const image of await scanImageParts(a))parts.push({role:a.asset_type==='explanation'?'answer':'question',image});}let combined='';for(let i=0;i<parts.length;i+=4){button.textContent=`読み取り中 ${Math.min(i+4,parts.length)} / ${parts.length}枚…`;const r=await repo.scan({questionNumber:q.question_number,images:parts.slice(i,i+4)});combined+=(combined?'\n':'')+r.text;raw=combined;q.ocr_text=raw;await localPut(tempKey('draft'),q);}raw=combined;applyScan(splitScanText(combined));}catch(e){q.ocr_text=raw;await localPut(tempKey('draft'),q);toast(e.message||'写真を読み取れませんでした。写真と入力内容は下書きに残しています。',true);}finally{saving=false;if(editor===q||editor?.id===q.id)renderEditor();}}
